function maxWater(heights) {
  let left = 0;
  let right = heights.length - 1;
  let best = 0;
  while (left < right) {
    const width = right - left;
    const level = Math.min(heights[left], heights[right]);
    best = Math.max(best, level * width);
    // the shorter wall limits every container it is part of; discard it
    if (heights[left] < heights[right]) {
      left++;
    } else {
      right--;
    }
  }
  return best;
}

