function brute(h) {
  let best = 0;
  for (let i = 0; i < h.length; i++) for (let j = i + 1; j < h.length; j++) best = Math.max(best, Math.min(h[i], h[j]) * (j - i));
  return best;
}
let seed = 7;
const rand = () => { seed = (seed * 48271) % 2147483647; return seed % 20; };
for (let t = 0; t < 40; t++) {
  const h = Array.from({ length: 2 + (t % 12) }, rand);
  assertEqual(maxWater(h), brute(h), 'heights ' + JSON.stringify(h));
}
